import {Job, Queue} from 'kue';
import * as kue from 'kue';

class EmailQueue {
  public queue: Queue;

  constructor() {
    this.queue = kue.createQueue();
  }

  public run(){
    this.queue.process('email', this.sendMail);
  }

  private sendMail(job?: Job, done?: (error?: Error | null, data?: object) => void) {
    console.log('send mail');
    console.log(JSON.stringify(job));
    if (done) done(null, {})
  }
}

export default new EmailQueue();
